{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Background: There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The manuscript explicitly states the current state of knowledge (limited evidence on sustainability evaluation of EBIs) establishing an important uncertainty that motivates the review."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The paper explains the importance and need for the review—to improve understanding of sustainability evaluation and to address gaps in guidance on selecting theoretical approaches and measuring outcomes."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. We provide further insight by reporting when sustainability evaluations were performed (timing), and what methods, measures, and outcomes were reported in evaluations on the sustainability of EBIs in healthcare.",
      "reason": "The manuscript explicitly positions itself relative to existing syntheses and similar reviews, stating how it differs and builds on prior work."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review is of evaluation approaches for sustainability rather than a review of intervention effects; no intervention mechanism of action is proposed or required for the review's objectives."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines theoretical approaches and methods for evaluating sustainability rather than testing a specific complex intervention or presenting a logic model; no logic model is proposed or discussed as part of the review."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The manuscript explicitly states the review objective(s) in a question-style aim: to identify and synthesize approaches used to evaluate sustainability of EBIs and to enhance understanding of related elements (definitions, designs, methods, timing, measures, outcomes)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "We conducted an integrative review that followed Whittemore and Knafl's [12] five-stage methodological process: (1) problem identification; (2) literature search; (3) data evaluation; (4) data analysis (data reduction, display, comparison, and conclusions); and (5) presentation. Integrative reviews can include diverse data sources and do not restrict the type of study design.",
      "reason": "This review is an integrative review focused on evaluation approaches for sustainability of EBIs rather than a review of intervention effects; thus specifying planned comparisons using PICO is not applicable."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI (Note that inconsistent terminology for EBI is prominent and thus may be referred to as a QI intervention/ initia- tive in the literature).",
      "reason": "Table 1 explicitly lists study characteristics used to determine eligibility including study type, design/data collection requirements, theoretical approach, setting, and that studies must evaluate sustainability of an EBI."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. This review entailed a comprehensive search of published literature and rigorous review methods; however, we recognize that there is the possibility of incomplete retrieval of identified research. For example, all gray literature was excluded.",
      "reason": "The manuscript explicitly states report-level eligibility restrictions (published, English language, peer-reviewed primary studies) and that gray literature was excluded."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction was provided between excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence describes variables extracted and inclusion groups but does not specify the groups used in each synthesis nor link them to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. This review entailed a comprehensive search of published literature and rigorous review methods; however, we recognize that there is the possibility of incomplete retrieval of identified research. For example, all gray literature was excluded.",
      "reason": "The manuscript states notable restrictions (English language, published, peer-reviewed; exclusion of gray literature) and acknowledges potential incomplete retrieval, but does not provide a clear rationale explaining why these specific restrictions were imposed."
    }
  ],
  "confidence": 85
}

